head.script:
scwin.screenId = "jldfil30500";

///////// 1. 변수 및 선언 영역 /////////

scwin.chrNm1 = undefined;

scwin.chrNm2 = undefined;


///////// 2. 초기화 영역 /////////

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = async function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } },
        { childId: "ipt_checkChrgNm1", attr: "__items", fn: function () { return [[String(dma_chrgInfoVO.get("disclsChrgNm1")), ""]]; } },
        { childId: "ipt_checkChrgNm2", attr: "__items", fn: function () { return [[String(dma_chrgInfoVO.get("disclsChrgNm2")), ""]]; } },
        { childId: "rd_empNm", attr: "__items", fn: function () { return [["1", String(dma_chrgInfoVO.get("empNm"))], ["2", ""]]; } }];
    const root = (function () { try { const f = $c.win.getFrame(); return (f && f.render) ? f.render : null; } catch (e) { return null; } })();
    const hasText = function (t) { return /[가-힣A-Za-z0-9]/.test(String(t == null ? "" : t)); };
    let applied = 0;
    for (let i = 0; i < attrRealsList.length; i++) {
        const a = attrRealsList[i];
        const comp = $c.util.getComponent(a.childId);
        const el = (comp && comp.getID && root) ? root.querySelector("#" + comp.getID()) : null;
        if (!comp && !el) { console.warn("[sdd] 속성 실현 대상 부재: " + a.childId); continue; }
        let v;
        try { v = a.fn(); } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId + "." + a.attr }); continue; }
        if (a.attr === "style") {
            if (comp && typeof comp.setStyle === "function") {
                const decls = String(v).split(";");
                for (let di = 0; di < decls.length; di++) {
                    const kv = decls[di].split(":");
                    if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
                }
            } else if (el) { el.style.cssText = (el.style.cssText || "") + ";" + v; }
        } else if (a.attr === "label") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); } else if (el) { el.textContent = v; }
        } else if (a.attr === "__value") {
            if (comp && typeof comp.setValue === "function") { comp.setValue(v); }
        } else if (a.attr === "__items") {
            if (comp && typeof comp.addItem === "function" && v && v.length) {
                let hasVal = false;
                for (let ii = 0; ii < v.length; ii++) { if (hasText(v[ii][0]) || hasText(v[ii][1])) { hasVal = true; break; } }
                if (hasVal) {
                    if (typeof comp.removeAll === "function") { comp.removeAll(); }
                    for (let ij = 0; ij < v.length; ij++) {
                        const lb = String(v[ij][1] || "");
                        comp.addItem(String(v[ij][0] || ""), hasText(lb) ? lb : "");
                    }
                }
            }
        } else if (a.attr === "class") {
            if (el) { el.className = v; }
        } else if (a.attr === "__html") {
            if (el && !el.querySelector('[class*="w2"], input, select, textarea, button')) { el.innerHTML = v; }
        } else if (el) {
            el.setAttribute(a.attr, v);
            if (a.attr === "src" && el.tagName === "IMG") { el.src = v; }
        }
        applied++;
    }
    return applied;
};

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_when_20", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "c_otherwise_23", fn: function(){ return (!(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// [A] 초기 목록 미해결 — jldfil30500: 진입 키 telreqnote 는 알지만 그 URL 을 쓰는 tx 가 화면에 없다(URL 을 지어내지 않는다) · 자기 목록 tx 0


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.i = undefined; scwin.j = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_attrReals();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil30500.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.ipt_checkChrgNm1_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_checkChrgNm1_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_checkChrgNm1_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.showHideTelNo(1)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30500.ipt_checkChrgNm1_onclick' }); }
};

/**
 * @event
 * @name scwin.ipt_checkChrgNm2_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_checkChrgNm2_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_checkChrgNm2_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.showHideTelNo(2)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30500.ipt_checkChrgNm2_onclick' }); }
};

/**
 * @event
 * @name scwin.ipt_checkChrgNm3_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.ipt_checkChrgNm3_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin ipt_checkChrgNm3_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.changeStatus()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30500.ipt_checkChrgNm3_onclick' }); }
};

/**
 * @event
 * @name scwin.img_121_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_121_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_121_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.send()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30500.img_121_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_send
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_send = async function () {
    const sbmOptions = {
        id: "tx_fn_send",
        method: "post",
        action: "/issue/telReqNote.do",
        ref: "dma_sendReq",
        target: "dlt_teamInfoVO=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil30500.tx_fn_send" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.send
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.send = async function () {
    /* sdd-asis-lifecycle:begin fn_send — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.telReqNoteForm || { elements: [] });
    if (!(String($c.util.getComponent('ipt_checkChrgNm1').getValue() || "") !== "") && !(String($c.util.getComponent('ipt_checkChrgNm2').getValue() || "") !== "") && !(String($c.util.getComponent('ipt_checkChrgNm3').getValue() || "") !== "")) {
        await $c.win.alert("발송자를 선택하세요!");
        return;
    }
    if ((String($c.util.getComponent('ipt_checkChrgNm3').getValue() || "") !== "")) {
        if (($c.util.getComponent('ipt_disclsChrgNm3').getValue() == null ? '' : String($c.util.getComponent('ipt_disclsChrgNm3').getValue())) === '') {
            await $c.win.alert("발송자명을 입력하세요!");
            return;
        }
        if (($c.util.getComponent('ipt_telNo3').getValue() == null ? '' : String($c.util.getComponent('ipt_telNo3').getValue())) === '' && ($c.util.getComponent('ipt_cellPhoneNo3').getValue() == null ? '' : String($c.util.getComponent('ipt_cellPhoneNo3').getValue())) === '') {
            await $c.win.alert("연락처를 입력하세요!");
            return;
        }
    }
    if ((String($c.util.getComponent('ipt_checkChrgNm1').getValue() || "") !== "")) {
        $c.util.getComponent('dma_sendReq').set('disclsChrgNm1', $c.util.getComponent('ipt_checkChrgNm1').getValue());
        $c.util.getComponent('dma_sendReq').set('telNo1', '' + dma_chrgInfoVO.get("telNo1") + '');
        $c.util.getComponent('dma_sendReq').set('cellPhoneNo1', '' + dma_chrgInfoVO.get("cellPhoneNo1") + '');
    }
    if ((String($c.util.getComponent('ipt_checkChrgNm2').getValue() || "") !== "")) {
        $c.util.getComponent('dma_sendReq').set('disclsChrgNm2', $c.util.getComponent('ipt_checkChrgNm2').getValue());
        $c.util.getComponent('dma_sendReq').set('telNo2', '' + dma_chrgInfoVO.get("telNo2") + '');
        $c.util.getComponent('dma_sendReq').set('cellPhoneNo2', '' + dma_chrgInfoVO.get("cellPhoneNo2") + '');
    }
    for (scwin.i = 0; scwin.i < $c.util.getComponent('rd_empNm').length; scwin.i++) {
        if ($c.util.getComponent('rd_empNm')[scwin.i].checked) {
            const obj = $c.util.getComponent('rd_empNm')[scwin.i];
            const selNo = $c.util.getComponent('rd_empNm')[scwin.i].value;
            if (selNo != null && selNo === "1") {
                $c.util.getComponent('dma_sendReq').set('rcvrEmpNo', obj.empNo);
                $c.util.getComponent('dma_sendReq').set('rcvrEmail', obj.email);
            } else {
                const empList = $c.util.getComponent('slc_empNm2');
                for (scwin.j = 0; scwin.j < empList.length; scwin.j++) {
                    if (empList[scwin.j].selected) {
                        $c.util.getComponent('dma_sendReq').set('rcvrEmpNo', empList[scwin.j].value);
                        $c.util.getComponent('dma_sendReq').set('rcvrEmail', empList[scwin.j].email);
                    }
                }
            }
        }
    }
    if ((String($c.util.getComponent('ipt_telRcvPosblTm').getValue() || "") !== "")) {
        $c.util.getComponent('dma_sendReq').set('telRcvPosblStrtTm', $c.util.getComponent('slc_time1').getValue());
        $c.util.getComponent('dma_sendReq').set('telRcvPosblEndTm', $c.util.getComponent('slc_time2').getValue());
    }
    frm.action = 'telReqNote.do';
    $c.util.getComponent('dma_sendReq').set('method', 'registerTelReqNote');
    { const nr = await scwin.tx_fn_send(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil30501/jldfil30501.xml", { "disclsChrgNm1": $c.util.getComponent('ipt_checkChrgNm1').getValue(), "telNo1": '' + dma_chrgInfoVO.get("telNo1") + '', "cellPhoneNo1": '' + dma_chrgInfoVO.get("cellPhoneNo1") + '', "disclsChrgNm2": $c.util.getComponent('ipt_checkChrgNm2').getValue(), "telNo2": '' + dma_chrgInfoVO.get("telNo2") + '', "cellPhoneNo2": '' + dma_chrgInfoVO.get("cellPhoneNo2") + '', "rcvrEmpNo": obj.empNo, "rcvrEmail": obj.email, "telRcvPosblStrtTm": $c.util.getComponent('slc_time1').getValue(), "telRcvPosblEndTm": $c.util.getComponent('slc_time2').getValue(), "method": 'registerTelReqNote' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeStatus
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeStatus = function () {
    /* sdd-asis-lifecycle:begin fn_changeStatus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.telReqNoteForm || { elements: [] });
    if ((String($c.util.getComponent('ipt_checkChrgNm3').getValue() || "") !== "")) {
        $c.util.getComponent('ipt_disclsChrgNm3').readOnly = false;
        $c.util.getComponent('ipt_telNo3').readOnly = false;
        $c.util.getComponent('ipt_cellPhoneNo3').readOnly = false;
    } else {
        $c.util.getComponent("ipt_disclsChrgNm3").setValue("");
        $c.util.getComponent("ipt_telNo3").setValue("");
        $c.util.getComponent("ipt_cellPhoneNo3").setValue("");
        $c.util.getComponent('ipt_disclsChrgNm3').readOnly = true;
        $c.util.getComponent('ipt_telNo3').readOnly = true;
        $c.util.getComponent('ipt_cellPhoneNo3').readOnly = true;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.showHideTelNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param no
 * @returns
 * @hidden N
*/
scwin.showHideTelNo = function (no) {
    /* sdd-asis-lifecycle:begin fn_showHideTelNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.telReqNoteForm || { elements: [] });
    if (no === "1") {
        if ((String($c.util.getComponent('ipt_checkChrgNm1').getValue() || "") !== "")) {
            var divObj = $c.util.getComponent("div_chrg" + no);
            divObj.style.display = '';
        } else {
            var divObj = $c.util.getComponent("div_chrg" + no);
            divObj.style.display = 'none';
        }
    } else {
        if ((String($c.util.getComponent('ipt_checkChrgNm2').getValue() || "") !== "")) {
            var divObj = $c.util.getComponent("div_chrg" + no);
            divObj.style.display = '';
        } else {
            var divObj = $c.util.getComponent("div_chrg" + no);
            divObj.style.display = 'none';
        }
    }
    /* sdd-asis-lifecycle:end */
};
